select json_build_object(
 'types',(select json_agg(format('create type public.%I as (%s)',c.relname,(select string_agg(format('%I %s',a.attname,format_type(a.atttypid,a.atttypmod)),',' order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='c'),
 'tables',(select json_agg(x) from(select c.relname name,format('create table public.%I (%s)',c.relname,string_agg(format('%I %s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),case when a.attidentity='a' then ' generated always as identity' when a.attidentity='d' then ' generated by default as identity' when d.adbin is not null then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end,case when a.attnotnull then ' not null' else '' end),',' order by a.attnum)) ddl
 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='public' and c.relkind in('r','p') group by c.oid,c.relname)x),
 'sequences',(select json_agg(format('create sequence if not exists public.%I',c.relname)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='S' and not exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='i')),
 'constraints',(select json_agg(format('alter table %s add constraint %I %s',c.conrelid::regclass,c.conname,pg_get_constraintdef(c.oid))) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public' and c.contype in('p','u','c','f')),
 'indexes',(select json_agg(pg_get_indexdef(i.indexrelid)) from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not exists(select 1 from pg_constraint k where k.conindid=i.indexrelid and k.contype in('p','u','x'))),
 'triggers',(select json_agg(pg_get_triggerdef(t.oid)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal),
 'rls',(select json_agg(format('alter table public.%I enable row level security',c.relname)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in('r','p') and c.relrowsecurity),
 'policies',(select json_agg(format('create policy %I on public.%I as %s for %s to %s %s %s',p.polname,c.relname,case when p.polpermissive then 'permissive' else 'restrictive' end,case p.polcmd when 'r' then 'select' when 'a' then 'insert' when 'w' then 'update' when 'd' then 'delete' else 'all' end,(select string_agg(case when x=0 then 'public' else quote_ident(pg_get_userbyid(x)) end,',') from unnest(p.polroles)x),case when p.polqual is null then '' else 'using ('||pg_get_expr(p.polqual,p.polrelid)||')' end,case when p.polwithcheck is null then '' else 'with check ('||pg_get_expr(p.polwithcheck,p.polrelid)||')' end)) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
 'table_grants',(select json_agg(format('grant %s on table public.%I to %s',a.privilege_type,c.relname,case when a.grantee=0 then 'public' else quote_ident(pg_get_userbyid(a.grantee)) end)) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where n.nspname='public' and c.relkind in('r','p') and (a.grantee=0 or pg_get_userbyid(a.grantee) in('anon','authenticated','service_role'))),
 'function_grants',(select json_agg(format('grant execute on function %s to %s',p.oid::regprocedure,case when a.grantee=0 then 'public' else quote_ident(pg_get_userbyid(a.grantee)) end)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where n.nspname='public' and p.prokind='f' and (a.grantee=0 or pg_get_userbyid(a.grantee) in('anon','authenticated','service_role')))
) schema;
